// Unicode/CLDRから日英検索用JSONと画面の版・hashを作る。Androidにも同じJSONを同梱する。
// node .github/scripts/vendor/fetch-vendor.js → node .github/scripts/generate-magi-emoji.mjs [--check]
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { resolve, dirname } from 'node:path';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';

const root = fileURLToPath(new URL('../../', import.meta.url));
const vendor = resolve(root, 'assets/vendor/unicode-emoji@18.0');
const read = name => readFileSync(resolve(vendor, name), 'utf8');
const key = s => s.replace(/\uFE0F/g, '');
const decode = s => s.replace(/&#(x[0-9a-f]+|\d+);|&(amp|lt|gt|quot|apos);/gi, (_, n, word) =>
  n ? String.fromCodePoint(n[0] === 'x' ? parseInt(n.slice(1), 16) : Number(n)) : ({ amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" })[word]);
function annotations(lang) {
  const result = new Map();
  for (const kind of ['annotations', 'annotationsDerived']) {
    const xml = read(kind + '-' + lang + '.xml').replace(/<!--[\s\S]*?-->/g, '');
    for (const [, attrs, value] of xml.matchAll(/<annotation\b([^>]+)>([^<]*)<\/annotation>/g)) {
      const cp = key(decode(attrs.match(/\bcp="([^"]*)"/)[1])), text = decode(value).trim();
      if (!text || text === '↑↑↑') continue;
      const row = result.get(cp) || { name: '', terms: [] };
      if (/\btype="tts"/.test(attrs)) row.name = text;
      else row.terms.push(...text.split(/\s*\|\s*/));
      result.set(cp, row);
    }
  }
  return result;
}
const en = annotations('en'), ja = annotations('ja');
const groups = ['Smileys & Emotion', 'People & Body', 'Animals & Nature', 'Food & Drink', 'Travel & Places', 'Activities', 'Objects', 'Symbols', 'Flags'];
const rows = [];
let group;
for (const line of read('emoji-test.txt').split(/\r?\n/)) {
  if (line.startsWith('# group: ')) group = line.slice(9);
  const match = line.match(/^([0-9A-F ]+)\s*;\s*(fully-qualified|component)\s*#\s*\S+\s+E[\d.]+\s+(.+)$/);
  if (!match) continue;
  const emoji = String.fromCodePoint(...match[1].trim().split(/\s+/).map(n => parseInt(n, 16)));
  const english = en.get(key(emoji)), japanese = ja.get(key(emoji));
  rows.push([emoji, group === 'Component' ? 1 : groups.indexOf(group), english?.name || match[3], japanese?.name || match[3],
    [...new Set([...(english?.terms || []), ...(japanese?.terms || [])])].join(' ')]);
}
assert(rows.length > 3900);
assert.equal(new Set(rows.map(r => r[0])).size, rows.length);
assert(rows.every(r => r[1] >= 0 && r[3]));
const start = '// AGENT_EMOJI_CATALOG_BEGIN', end = '// AGENT_EMOJI_CATALOG_END';
const filename = 'magi-emoji-18.0-cldr49.json';
const payload = JSON.stringify({ schema: 1, unicode: '18.0', cldr: '49', license: read('LICENSE').trim(), emojis: rows }) + '\n';
const metadata = { file: filename, unicode: '18.0', cldr: '49', count: rows.length, sha256: createHash('sha256').update(payload).digest('hex') };
const block = start + '\n// Generated by generate-magi-emoji.mjs. 一覧は「＋」を開いたときだけ読む。\n'
  + 'var AGENT_EMOJI_ASSET = ' + JSON.stringify(metadata) + ';\nvar AGENT_EMOJI_CATALOG = null;\n' + end;
for (const name of ['data/' + filename, 'magi-app/www/data/' + filename]) {
  const file = resolve(root, name);
  if (process.argv.includes('--check')) assert.equal(readFileSync(file, 'utf8'), payload, name + ': regenerate emoji JSON');
  else { mkdirSync(dirname(file), { recursive: true }); writeFileSync(file, payload); }
}
for (const name of ['index.html', 'magi-app/www/app.js']) {
  const file = resolve(root, name), source = readFileSync(file, 'utf8');
  const a = source.indexOf(start), b = source.indexOf(end);
  const next = a >= 0 ? source.slice(0, a) + block + source.slice(b + end.length)
    : source.replace('var AGENT_REACTIONS_QUICK', block + '\nvar AGENT_REACTIONS_QUICK');
  assert(next.includes(block), name + ': catalog insertion');
  if (process.argv.includes('--check')) assert.equal(source, next, name + ': regenerate emoji catalog');
  else writeFileSync(file, next);
}
console.log(JSON.stringify({ emojis: rows.length, groups: groups.length, jsonBytes: Buffer.byteLength(payload), inlineBytes: Buffer.byteLength(block), check: process.argv.includes('--check') }));
